"""The words of the demo feed's long tail (scripts/generate_feed.py): invented complaints, written by hand.

A scene is (needs, subject, body), optionally with `heat=True` (a threat: the first option goes to a person, high
risk). `needs` are facts that must hold for the user on the ticket's day, so nobody complains about a plan they do not
have. Slots come from the user's profile as of that day: {price} {plan} {store} {paid} {first} {orig} {ends} {bi} {days}.
"""

from __future__ import annotations


def S(needs: str, subject: str, body: str, **extra) -> dict:
    return {"needs": needs.split(), "subject": subject, "body": body, **extra}


